package com.hbm.client.oreslopper;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.fluid.*;import com.hbm.item.battery.BatteryItem;import com.hbm.item.fluid.client.FluidInfo;import com.hbm.machine.oreslopper.*;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
/** Original176x204 GUI, exact source vertical35px progress, 52px energy and two native tanks. */
public final class OreSlopperScreen extends LegacyContainerScreen<OreSlopperMenu> {
 public OreSlopperScreen(OreSlopperMenu menu,Inventory inv,Component title){super(menu,inv,title,OreSlopperContent.id("textures/gui/processing/gui_ore_slopper.png"),176,204);}
 private OreSlopperBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof OreSlopperBlockEntity machine?machine:null;}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,88-font.width(title)/2-9,6,4210752,false);g.drawString(font,playerInventoryTitle,8,110,4210752,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);if(menu.processing()){int height=(int)(menu.progress()*35);drawLegacyRegion(g,62,52-height,176,34-height,34,height);}int energy=(int)(menu.power()*52/OreSlopperBlockEntity.MAX_POWER);drawLegacyRegion(g,8,70-energy,176,86-energy,16,energy);if(menu.power()>=menu.consumption())drawLegacyRegion(g,12,4,202,34,9,12);var m=machine();if(m!=null){tank(g,m.tanks[0],26);tank(g,m.tanks[1],116);}}
 private void tank(GuiGraphics g,FluidTank tank,int x){int remaining=tank.getFill()*52/tank.getMaxFill(),color=tank.getTankType().getTint();if(remaining<=0)return;g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);int bottom=70;while(remaining>0){int height=Math.min(remaining,16);g.blit(tank.getTankType().getTexture(),leftPos+x,topPos+bottom-height,0,16-height,16,height,16,16);remaining-=height;bottom-=height;}g.setColor(1,1,1,1);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var m=machine();if(m!=null){if(legacyInfoHovered(x,y,26,18,16,52))info(g,m.tanks[0],x,y);if(legacyInfoHovered(x,y,116,18,16,52))info(g,m.tanks[1],x,y);}if(legacyInfoHovered(x,y,8,18,16,52))g.renderTooltip(font,Component.literal(BatteryItem.shortNumber(menu.power())+"/"+BatteryItem.shortNumber(OreSlopperBlockEntity.MAX_POWER)+"HE"),x,y);}
 private void info(GuiGraphics g,FluidTank tank,int x,int y){var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+"/"+tank.getMaxFill()+"mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}
}
